description:
Two pieces of an input layer:

```cpp
struct Vector2 { float x, y; };

Vector2 radialDeadZone(Vector2 stick, float dz);

enum class Action { Left, Right, Jump, Pause };

class Bindings
{
public:
    void bind(Action a, int key);              // a key belongs to at most one action
    void unbind(int key);
    bool down(Action a, const std::set<int>& keysDown) const;
    std::vector<int> keysFor(Action a) const;  // in increasing order
};
```

**radialDeadZone**: take the stick's length. Below `dz`, the result is `(0, 0)`. Otherwise keep the direction and rescale the length from `dz..1` to `0..1`; a length above 1 (sticks can report slightly more on diagonals) counts as 1.

**Bindings**: an action can have any number of keys. Binding a key that already belongs to another action **moves** it to the new one, so one key never does two things. `down` is true if any of the action's keys is in `keysDown`.

starter.solution.cpp:
#include <set>
#include <vector>

struct Vector2 { float x, y; };

Vector2 radialDeadZone(Vector2 stick, float dz) { return stick; }

enum class Action { Left, Right, Jump, Pause };

class Bindings
{
public:
    void bind(Action a, int key) {}
    void unbind(int key) {}
    bool down(Action a, const std::set<int>& keysDown) const { return false; }
    std::vector<int> keysFor(Action a) const { return {}; }
};

solution.solution.cpp:
#include <algorithm>
#include <cmath>
#include <map>
#include <set>
#include <vector>

struct Vector2 { float x, y; };

Vector2 radialDeadZone(Vector2 stick, float dz)
{
    const float len{ std::sqrt(stick.x * stick.x + stick.y * stick.y) };
    if (len < dz || len == 0) return { 0, 0 };
    const float scaled{ (std::min(len, 1.0f) - dz) / (1.0f - dz) };
    return { stick.x / len * scaled, stick.y / len * scaled };
}

enum class Action { Left, Right, Jump, Pause };

class Bindings
{
public:
    void bind(Action a, int key) { m_keys[key] = a; }
    void unbind(int key) { m_keys.erase(key); }

    bool down(Action a, const std::set<int>& keysDown) const
    {
        for (const auto& [key, action] : m_keys)
            if (action == a && keysDown.count(key)) return true;
        return false;
    }

    std::vector<int> keysFor(Action a) const
    {
        std::vector<int> out;
        for (const auto& [key, action] : m_keys) if (action == a) out.push_back(key);
        return out;
    }

private:
    std::map<int, Action> m_keys;
};

unitTests:
TEST("inside the dead zone") { const Vector2 v = radialDeadZone({ 0.1f, -0.1f }, 0.2f); CHECK_NEAR(v.x, 0.0, 1e-6); CHECK_NEAR(v.y, 0.0, 1e-6); }
TEST("rescaled") { const Vector2 v = radialDeadZone({ 0.6f, 0.0f }, 0.2f); CHECK_NEAR(v.x, 0.5, 1e-5); CHECK_NEAR(v.y, 0.0, 1e-5); }
TEST("direction kept") { const Vector2 v = radialDeadZone({ 0.3f, 0.4f }, 0.0f); CHECK_NEAR(v.x, 0.3, 1e-5); CHECK_NEAR(v.y, 0.4, 1e-5); const Vector2 w = radialDeadZone({ 0.0f, -0.6f }, 0.2f); CHECK_NEAR(w.y, -0.5, 1e-5); }
TEST("over full length") { const Vector2 v = radialDeadZone({ 0.9f, 0.9f }, 0.1f); CHECK_NEAR(std::sqrt(v.x * v.x + v.y * v.y), 1.0, 1e-5); CHECK_NEAR(v.x, v.y, 1e-6); }
TEST("bindings") {
    Bindings b; b.bind(Action::Left, 65); b.bind(Action::Left, 263); b.bind(Action::Jump, 32);
    CHECK(b.down(Action::Left, { 263 })); CHECK(!b.down(Action::Right, { 263 })); CHECK(!b.down(Action::Jump, {}));
    CHECK_EQ(b.keysFor(Action::Left), (std::vector<int>{ 65, 263 }));
}
TEST("a key moves to its new action") {
    Bindings b; b.bind(Action::Jump, 32); b.bind(Action::Pause, 32);
    CHECK(!b.down(Action::Jump, { 32 })); CHECK(b.down(Action::Pause, { 32 })); CHECK(b.keysFor(Action::Jump).empty());
    b.unbind(32); CHECK(!b.down(Action::Pause, { 32 }));
}

